CREATE OR REPLACE FUNCTION public.trigger_recompute_event_attendees_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    perform public.recompute_event_attendees_count(new.event_id);
    return new;
  elsif tg_op = 'UPDATE' then
    if old.event_id is distinct from new.event_id then
      perform public.recompute_event_attendees_count(old.event_id);
    end if;
    perform public.recompute_event_attendees_count(new.event_id);
    return new;
  elsif tg_op = 'DELETE' then
    perform public.recompute_event_attendees_count(old.event_id);
    return old;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_admin_request(p_user_id uuid, p_email character varying, p_reason text, p_first_name character varying DEFAULT NULL::character varying, p_last_name character varying DEFAULT NULL::character varying, p_contact_number character varying DEFAULT NULL::character varying, p_organization character varying DEFAULT NULL::character varying, p_experience_level character varying DEFAULT 'INTERMEDIATE'::character varying, p_intended_use text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    request_id UUID;
    existing_status VARCHAR;
    admin_user_id UUID;
    v_wait_count INTEGER := 0;
    v_user_exists BOOLEAN := FALSE;
    v_admin_count INTEGER;
    v_final_status VARCHAR;
BEGIN
    -- Wait up to 5 seconds for the user to be created in public.users by the trigger
    WHILE v_wait_count < 50 LOOP 
        IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
            v_user_exists := TRUE;
            EXIT;
        END IF;
        PERFORM pg_sleep(0.1);
        v_wait_count := v_wait_count + 1;
    END LOOP;

    IF NOT v_user_exists THEN
        RAISE EXCEPTION 'User profile not yet created. Please try again in a moment.';
    END IF;

    -- Check if user already has a request
    SELECT status INTO existing_status 
    FROM public.admin_requests 
    WHERE user_id = p_user_id;
    
    IF existing_status IS NOT NULL THEN
        RAISE EXCEPTION 'You already have an admin request with status: %', existing_status;
    END IF;
    
    -- Check if user is already an admin
    IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND role = 'ADMIN') THEN
        RAISE EXCEPTION 'You are already an admin';
    END IF;

    -- Count existing admins to check if we need to bootstrap
    SELECT COUNT(*) INTO v_admin_count FROM public.users WHERE role = 'ADMIN';
    v_final_status := CASE WHEN v_admin_count = 0 THEN 'APPROVED' ELSE 'PENDING' END;
    
    -- Create the request
    INSERT INTO public.admin_requests (
        user_id, 
        email, 
        first_name, 
        last_name, 
        contact_number, 
        reason, 
        organization, 
        experience_level, 
        intended_use,
        status,
        reviewed_at,
        review_notes
    )
    VALUES (
        p_user_id, 
        p_email, 
        p_first_name, 
        p_last_name, 
        p_contact_number, 
        p_reason, 
        p_organization, 
        p_experience_level, 
        p_intended_use,
        v_final_status,
        CASE WHEN v_final_status = 'APPROVED' THEN now() ELSE NULL END,
        CASE WHEN v_final_status = 'APPROVED' THEN 'System: Automatically approved as first administrator' ELSE NULL END
    )
    RETURNING id INTO request_id;

    -- If automatically approved, update roles
    IF v_final_status = 'APPROVED' THEN
        -- Link request with its own ID as the reviewer (for history)
        UPDATE public.admin_requests SET reviewed_by = p_user_id WHERE id = request_id;

        -- Update user role in public.users
        -- Removed updated_at as it doesn't exist in the users table
        UPDATE public.users
        SET role = 'ADMIN'
        WHERE id = p_user_id;

        -- Update auth.users metadata
        UPDATE auth.users
        SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('role', 'ADMIN')
        WHERE id = p_user_id;
        
        -- Log action
        INSERT INTO public.admin_audit_log (admin_id, action, target_user_id, details)
        VALUES (NULL, 'SYSTEM_AUTO_APPROVE_FIRST_ADMIN', p_user_id, jsonb_build_object('request_id', request_id));
    END IF;
    
    -- Return JSON with metadata
    RETURN json_build_object(
        'request_id', request_id,
        'status', v_final_status,
        'is_bootstrapped', (v_admin_count = 0)
    );
END;
$function$

