CREATE OR REPLACE FUNCTION public.send_organization_invitation(p_organization_id uuid, p_email character varying, p_role character varying DEFAULT 'USER'::character varying, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    invitation_id UUID;
    inviter_id UUID;
    org_name VARCHAR;
    existing_invitation_id UUID;
BEGIN
    inviter_id := auth.uid();
    IF inviter_id IS NULL THEN
        RAISE EXCEPTION 'User must be authenticated';
    END IF;

    RAISE NOTICE 'User % sending invitation to % for org %', inviter_id, p_email, p_organization_id;

    -- ... rest of function remains the same but with logging ...
    -- (keeping existing logic, just adding notice statements)

    -- Check permissions and validate
    IF NOT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = inviter_id
        AND organization_id = p_organization_id
        AND role_in_org IN ('OWNER', 'ADMIN')
    ) THEN
        RAISE EXCEPTION 'Only organization owners and admins can send invitations';
    END IF;

    SELECT name INTO org_name FROM public.organizations WHERE id = p_organization_id;

    -- Check for existing pending invitation
    SELECT id INTO existing_invitation_id
    FROM public.organization_invitations
    WHERE organization_id = p_organization_id
    AND email = p_email
    AND status = 'PENDING'
    AND expires_at > NOW();

    IF existing_invitation_id IS NOT NULL THEN
        RAISE EXCEPTION 'A pending invitation already exists for this email';
    END IF;

    -- Check if user is already a member
    IF EXISTS (
        SELECT 1 FROM public.users u
        JOIN auth.users au ON u.id = au.id
        WHERE au.email = p_email
        AND u.organization_id = p_organization_id
    ) THEN
        RAISE EXCEPTION 'User is already a member of this organization';
    END IF;

    -- Create invitation
    INSERT INTO public.organization_invitations (
        organization_id, email, invited_by, role, message
    )
    VALUES (p_organization_id, p_email, inviter_id, p_role, p_message)
    RETURNING id INTO invitation_id;

    RAISE NOTICE 'Invitation % created for % to join org % (%)', invitation_id, p_email, org_name, p_organization_id;

    -- Create notification (with error handling)
    IF EXISTS (SELECT 1 FROM auth.users WHERE email = p_email) THEN
        BEGIN
            PERFORM public.create_notification_from_template(
                (SELECT id FROM auth.users WHERE email = p_email),
                'ORGANIZATION_INVITATION',
                jsonb_build_object(
                    'organization_name', org_name,
                    'inviter_name', (SELECT COALESCE(first_name || ' ' || last_name, email) FROM public.users WHERE id = inviter_id),
                    'role', p_role,
                    'invitation_id', invitation_id
                )
            );
            RAISE NOTICE 'Notification sent to % for invitation %', p_email, invitation_id;
        EXCEPTION WHEN undefined_function THEN
            RAISE NOTICE 'Notification template ORGANIZATION_INVITATION not found - skipping notification';
        WHEN OTHERS THEN
            RAISE NOTICE 'Failed to send invitation notification: %', SQLERRM;
        END;
    END IF;

    RETURN invitation_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_booking_admin(booking_id uuid)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    booking_record bookings;
BEGIN
    -- Check if the current user is an admin
    IF NOT EXISTS (
        SELECT 1 FROM users
        WHERE id = auth.uid()
        AND role = 'ADMIN'
    ) THEN
        RAISE EXCEPTION 'Access denied: Only administrators can cancel bookings through this method';
    END IF;

    -- Update the booking status
    UPDATE bookings
    SET status = 'CANCELLED'
    WHERE id = booking_id
    RETURNING * INTO booking_record;

    -- Check if the booking was found and updated
    IF booking_record IS NULL THEN
        RAISE EXCEPTION 'Booking not found with ID: %', booking_id;
    END IF;

    RETURN booking_record;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_organization(p_name character varying, p_slug character varying, p_created_by uuid, p_description text DEFAULT NULL::text, p_subscription_plan character varying DEFAULT 'FREE'::character varying)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    org_id UUID;
    result json;
BEGIN
    -- Validation
    IF p_name IS NULL OR trim(p_name) = '' THEN RETURN json_build_object('success', false, 'error', 'invalid_name', 'details', 'Organization name is required'); END IF;
    IF p_slug IS NULL OR trim(p_slug) = '' THEN RETURN json_build_object('success', false, 'error', 'invalid_slug', 'details', 'Organization slug is required'); END IF;
    IF p_created_by IS NULL THEN RETURN json_build_object('success', false, 'error', 'not_authenticated', 'details', 'User must be authenticated'); END IF;
    IF EXISTS (SELECT 1 FROM organizations WHERE slug = trim(lower(p_slug))) THEN
        RETURN json_build_object('success', false, 'error', 'slug_exists', 'details', 'Organization slug already exists: ' || p_slug);
    END IF;

    -- Create organization
    INSERT INTO organizations (name, slug, description, created_by, subscription_plan, subscription_start_date, current_users_count)
    VALUES (trim(p_name), trim(lower(p_slug)), nullif(trim(p_description), ''), p_created_by, p_subscription_plan, NOW(), 1)
    RETURNING id INTO org_id;

    -- Insert into organization_members (Critical Step)
    INSERT INTO organization_members (user_id, organization_id, role_in_org, is_org_admin, joined_at)
    VALUES (p_created_by, org_id, 'OWNER', TRUE, NOW());

    -- Update users table legacy fields
    UPDATE users
    SET organization_id = org_id, role_in_org = 'OWNER', is_org_admin = TRUE, joined_at = NOW(), last_active_organization_id = org_id
    WHERE id = p_created_by;

    -- Create default Event Space
    INSERT INTO event_spaces (name, description, slug, organization_id, created_by)
    VALUES ('General', 'Default event space', 'general', org_id, p_created_by);

    RETURN json_build_object('success', true, 'organization_id', org_id, 'organization_name', trim(p_name), 'organization_slug', trim(lower(p_slug)));
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', 'system_error', 'details', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_event_followers(p_event_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    event_record RECORD;
    follower_record RECORD;
    notification_count INTEGER := 0;
BEGIN
    -- Get event details
    SELECT e.*, c.name as category_name
    INTO event_record
    FROM events e
    LEFT JOIN categories c ON e.category_id = c.id
    WHERE e.id = p_event_id;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    -- Only notify if the event has a category AND the category exists
    IF event_record.category_id IS NULL OR event_record.category_name IS NULL THEN
        RETURN 0;
    END IF;

    -- Check if the notification template exists before proceeding
    IF NOT EXISTS (SELECT 1 FROM notification_templates WHERE type = 'CATEGORY_UPDATE' AND is_active = TRUE) THEN
        RETURN 0;
    END IF;

    -- Notify users following the event's category
    FOR follower_record IN
        SELECT f.follower_id
        FROM follows f
        LEFT JOIN notification_preferences np ON f.follower_id = np.user_id
        WHERE f.target_type = 'CATEGORY'
        AND f.target_id = event_record.category_id
        AND (np.category_updates IS NULL OR np.category_updates = TRUE)
    LOOP
        -- Try to create notification, but don't fail if it doesn't work
        BEGIN
            PERFORM create_notification_from_template(
                follower_record.follower_id,
                'CATEGORY_UPDATE',
                jsonb_build_object(
                    'category_name', event_record.category_name,
                    'event_title', event_record.title
                )
            );
            notification_count := notification_count + 1;
        EXCEPTION
            WHEN OTHERS THEN
                -- Log the error but continue
                RAISE NOTICE 'Failed to create notification for user %: %', follower_record.follower_id, SQLERRM;
        END;
    END LOOP;

    RETURN notification_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_admin_request(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
    UPDATE admin_requests 
    SET status = 'CANCELLED', updated_at = NOW()
    WHERE user_id = p_user_id AND status = 'PENDING';
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No pending request found for this user';
    END IF;
    
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.clean_old_notifications(days_to_keep integer DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM public.notifications 
    WHERE created_at < NOW() - INTERVAL '1 day' * days_to_keep
    AND is_read = TRUE;
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_notification_from_template(p_user_id uuid, p_type character varying, p_data jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    template_record RECORD;
    notification_id UUID;
    final_title TEXT;
    final_message TEXT;
BEGIN
    SELECT * INTO template_record 
    FROM public.notification_templates 
    WHERE type = p_type AND is_active = TRUE;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Template not found for type: %', p_type;
    END IF;
    
    final_title := template_record.title_template;
    final_message := template_record.message_template;
    
    -- Replace placeholders
    final_title := replace(final_title, '{{event_title}}', COALESCE(p_data->>'event_title', ''));
    final_title := replace(final_title, '{{category_name}}', COALESCE(p_data->>'category_name', ''));
    final_title := replace(final_title, '{{username}}', COALESCE(p_data->>'username', ''));
    final_title := replace(final_title, '{{target_type}}', COALESCE(p_data->>'target_type', ''));
    final_title := replace(final_title, '{{target_name}}', COALESCE(p_data->>'target_name', ''));
    
    final_message := replace(final_message, '{{event_title}}', COALESCE(p_data->>'event_title', ''));
    final_message := replace(final_message, '{{category_name}}', COALESCE(p_data->>'category_name', ''));
    final_message := replace(final_message, '{{time_until_event}}', COALESCE(p_data->>'time_until_event', ''));
    final_message := replace(final_message, '{{location}}', COALESCE(p_data->>'location', ''));
    final_message := replace(final_message, '{{username}}', COALESCE(p_data->>'username', ''));
    final_message := replace(final_message, '{{action}}', COALESCE(p_data->>'action', ''));
    final_message := replace(final_message, '{{target_type}}', COALESCE(p_data->>'target_type', ''));
    final_message := replace(final_message, '{{target_name}}', COALESCE(p_data->>'target_name', ''));
    
    SELECT public.create_notification(p_user_id, final_title, final_message, p_type, p_data, p_scheduled_at)
    INTO notification_id;
    
    RETURN notification_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_organization(p_organization_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_role VARCHAR;
    v_org_name VARCHAR;
BEGIN
    -- Permission Check
    SELECT role_in_org INTO v_user_role
    FROM public.users
    WHERE id = auth.uid() AND organization_id = p_organization_id;

    IF v_user_role != 'OWNER' THEN
        RAISE EXCEPTION 'Only the organization owner can delete the organization';
    END IF;

    SELECT name INTO v_org_name FROM public.organizations WHERE id = p_organization_id;

    -- Log Activity before deletion
    PERFORM public.log_organization_activity(
        p_organization_id,
        'ORGANIZATION_DELETED',
        'organization',
        p_organization_id,
        NULL,
        NULL,
        jsonb_build_object('name', v_org_name)
    );

    -- 1. Delete Invitations
    DELETE FROM public.organization_invitations WHERE organization_id = p_organization_id;

    -- 2. Update Users (Dissociate them)
    UPDATE public.users
    SET 
        organization_id = NULL,
        role_in_org = NULL,
        is_org_admin = FALSE,
        onboarding_step = 0
    WHERE organization_id = p_organization_id;

    -- 3. Delete Event Spaces
    -- Note: safe_delete_event_space is too complex for bulk deletion, 
    -- we do a direct delete here as the entire org is going away.
    DELETE FROM public.event_spaces WHERE organization_id = p_organization_id;

    -- 4. Delete Events 
    -- (Assuming events are tied to organization_id)
    DELETE FROM public.events WHERE organization_id = p_organization_id;

    -- 5. Delete the Organization itself
    DELETE FROM public.organizations WHERE id = p_organization_id;

    RETURN json_build_object(
        'success', true,
        'message', 'Organization and all associated data have been purged successfully.'
    );
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    affected_rows INTEGER;
BEGIN
    UPDATE public.notifications 
    SET is_read = TRUE, updated_at = NOW()
    WHERE user_id = p_user_id AND is_read = FALSE;
    
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    RETURN affected_rows;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_scheduled_notifications()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    notification_record RECORD;
    processed_count INTEGER := 0;
BEGIN
    -- Process event reminders
    PERFORM create_event_reminders();
    
    -- Mark scheduled notifications as sent
    UPDATE notifications 
    SET is_sent = TRUE, sent_at = NOW()
    WHERE scheduled_at <= NOW() 
    AND is_sent = FALSE;
    
    GET DIAGNOSTICS processed_count = ROW_COUNT;
    RETURN processed_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.report_review(p_review_id uuid, p_reporter_id uuid, p_reason character varying, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    report_id UUID;
BEGIN
    -- Check if user has already reported this review
    IF EXISTS (SELECT 1 FROM review_reports WHERE review_id = p_review_id AND reporter_id = p_reporter_id) THEN
        RAISE EXCEPTION 'User has already reported this review';
    END IF;
    
    -- Insert report
    INSERT INTO review_reports (review_id, reporter_id, reason, description)
    VALUES (p_review_id, p_reporter_id, p_reason, p_description)
    RETURNING id INTO report_id;
    
    -- Mark review as reported if multiple reports
    UPDATE reviews 
    SET is_reported = TRUE
    WHERE id = p_review_id AND (
        SELECT COUNT(*) FROM review_reports WHERE review_id = p_review_id
    ) >= 3;
    
    RETURN report_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.safe_delete_event_space(p_space_id uuid, p_user_id uuid, p_move_events_to_space_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    space_org_id UUID;
    user_org_id UUID;
    user_role_in_org VARCHAR;
    event_count INTEGER;
    total_spaces INTEGER;
    events_moved INTEGER := 0;
    target_space_id UUID;
    deletion_result INTEGER;
    space_name VARCHAR;
BEGIN
    -- Debug: Log the start of the function
    RAISE NOTICE 'Starting deletion for space_id: %, user_id: %', p_space_id, p_user_id;
    
    -- Get the space's organization and name
    SELECT organization_id, name INTO space_org_id, space_name
    FROM public.event_spaces 
    WHERE id = p_space_id;
    
    IF space_org_id IS NULL THEN
        RAISE EXCEPTION 'Event space not found';
    END IF;
    
    RAISE NOTICE 'Found space "%" in organization: %', space_name, space_org_id;
    
    -- Get user's organization and role
    SELECT organization_id, role_in_org INTO user_org_id, user_role_in_org
    FROM public.users 
    WHERE id = p_user_id;
    
    -- Check permissions
    IF user_org_id IS NULL OR user_org_id != space_org_id THEN
        RAISE EXCEPTION 'User does not have access to this event space';
    END IF;
    
    IF user_role_in_org NOT IN ('OWNER', 'ADMIN') THEN
        RAISE EXCEPTION 'Only organization owners and admins can delete event spaces';
    END IF;
    
    -- Count events in this space
    SELECT COUNT(*) INTO event_count
    FROM public.events 
    WHERE event_space_id = p_space_id;
    
    -- Count total spaces in organization
    SELECT COUNT(*) INTO total_spaces
    FROM public.event_spaces 
    WHERE organization_id = space_org_id;
    
    RAISE NOTICE 'Event count: %, Total spaces: %', event_count, total_spaces;
    
    -- BUSINESS LOGIC: Determine if deletion is allowed
    IF total_spaces <= 1 THEN
        -- This is the last (or only) space in the organization
        IF event_count > 0 THEN
            -- Last space with events - cannot delete
            RAISE EXCEPTION 'Cannot delete the last event space when it contains % events. Please move or delete the events first.', event_count;
        ELSE
            -- Last space with no events - can delete, but warn
            RAISE NOTICE 'Deleting the last event space in organization (no events to move)';
        END IF;
    ELSE
        -- There are other spaces, handle events if any
        IF event_count > 0 THEN
            RAISE NOTICE 'Multiple spaces available, will move % events', event_count;
        ELSE
            RAISE NOTICE 'No events to move, proceeding with deletion';
        END IF;
    END IF;
    
    -- STEP 1: Handle events if they exist AND there are alternative spaces
    IF event_count > 0 AND total_spaces > 1 THEN
        -- Find target space for events
        IF p_move_events_to_space_id IS NOT NULL THEN
            -- Validate the target space
            SELECT id INTO target_space_id
            FROM public.event_spaces 
            WHERE id = p_move_events_to_space_id 
            AND organization_id = space_org_id;
            
            IF target_space_id IS NULL THEN
                RAISE EXCEPTION 'Target event space not found or not in same organization';
            END IF;
        ELSE
            -- Find any other space in the same organization
            SELECT id INTO target_space_id
            FROM public.event_spaces 
            WHERE organization_id = space_org_id 
            AND id != p_space_id
            LIMIT 1;
            
            IF target_space_id IS NULL THEN
                RAISE EXCEPTION 'No alternative event space found';
            END IF;
        END IF;
        
        RAISE NOTICE 'Moving % events to space: %', event_count, target_space_id;
        
        -- Move the events
        UPDATE public.events 
        SET event_space_id = target_space_id
        WHERE event_space_id = p_space_id;
        
        GET DIAGNOSTICS events_moved = ROW_COUNT;
        RAISE NOTICE 'Actually moved % events', events_moved;
        
        -- Verify the move was successful
        IF events_moved != event_count THEN
            RAISE EXCEPTION 'Event move failed: expected to move % events, actually moved %', event_count, events_moved;
        END IF;
    END IF;
    
    -- STEP 2: Verify no events are left in the space
    SELECT COUNT(*) INTO event_count
    FROM public.events 
    WHERE event_space_id = p_space_id;
    
    IF event_count > 0 THEN
        RAISE EXCEPTION 'Cannot delete event space: % events still reference it after move attempt', event_count;
    END IF;
    
    RAISE NOTICE 'Confirmed no events left, proceeding with space deletion';
    
    -- STEP 3: Delete the event space
    DELETE FROM public.event_spaces 
    WHERE id = p_space_id AND organization_id = space_org_id;
    
    GET DIAGNOSTICS deletion_result = ROW_COUNT;
    RAISE NOTICE 'DELETE command affected % rows', deletion_result;
    
    -- Verify deletion
    IF deletion_result = 0 THEN
        -- Check if space still exists
        IF EXISTS (SELECT 1 FROM public.event_spaces WHERE id = p_space_id) THEN
            RAISE EXCEPTION 'Event space still exists after deletion attempt - may be protected by RLS policies or constraints';
        ELSE
            RAISE EXCEPTION 'No rows were deleted - space may not exist or user may not have permission';
        END IF;
    END IF;
    
    -- Final verification
    IF EXISTS (SELECT 1 FROM public.event_spaces WHERE id = p_space_id) THEN
        RAISE EXCEPTION 'Event space still exists after successful delete command - check for triggers or constraints';
    END IF;
    
    RAISE NOTICE 'Successfully deleted event space: % (%)', p_space_id, space_name;
    
    -- Return success result
    RETURN json_build_object(
        'success', true,
        'events_moved', events_moved,
        'moved_to_space_id', target_space_id,
        'space_name', space_name,
        'message', CASE 
            WHEN events_moved > 0 THEN 
                'Event space "' || space_name || '" deleted successfully. ' || events_moved || ' events were moved to another space.'
            ELSE 
                'Event space "' || space_name || '" deleted successfully.'
        END
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error occurred: %', SQLERRM;
        RETURN json_build_object(
            'success', false,
            'error', SQLERRM,
            'message', 'Failed to delete event space: ' || SQLERRM
        );
END;
$function$

CREATE OR REPLACE FUNCTION public.add_user_to_organization(p_user_id uuid, p_organization_id uuid, p_added_by uuid, p_role_in_org character varying DEFAULT 'USER'::character varying)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    org_owner_id UUID;
    current_user_count INTEGER;
    org_max_users INTEGER;
BEGIN
    -- Check if user adding is organization owner or admin
    SELECT created_by INTO org_owner_id 
    FROM public.organizations 
    WHERE id = p_organization_id;
    
    IF org_owner_id != p_added_by AND NOT EXISTS (
        SELECT 1 FROM public.users 
        WHERE id = p_added_by 
        AND organization_id = p_organization_id 
        AND role_in_org IN ('OWNER', 'ADMIN')
    ) THEN
        RAISE EXCEPTION 'Only organization owners and admins can add users';
    END IF;
    
    -- Check user limits (use different variable name to avoid ambiguity)
    SELECT current_users_count, max_users 
    INTO current_user_count, org_max_users
    FROM public.organizations 
    WHERE id = p_organization_id;
    
    IF current_user_count >= org_max_users THEN
        RAISE EXCEPTION 'Organization has reached maximum user limit';
    END IF;
    
    -- Add user to organization
    UPDATE public.users 
    SET 
        organization_id = p_organization_id,
        role_in_org = p_role_in_org,
        is_org_admin = (p_role_in_org IN ('OWNER', 'ADMIN')),
        joined_at = NOW()
    WHERE id = p_user_id;
    
    -- Update organization user count
    UPDATE public.organizations 
    SET current_users_count = current_users_count + 1
    WHERE id = p_organization_id;
    
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_member_role_in_organization(p_user_id uuid, p_organization_id uuid, p_new_role character varying, p_updated_by uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    updater_role VARCHAR(50);
    current_user_role VARCHAR(50);
BEGIN
    -- Check if the user making the update has permission (owner or admin)
    SELECT role_in_org INTO updater_role
    FROM public.users
    WHERE id = p_updated_by AND organization_id = p_organization_id;
    
    IF updater_role IS NULL OR (updater_role != 'OWNER' AND updater_role != 'ADMIN') THEN
        RAISE EXCEPTION 'Only organization owners and admins can update member roles';
    END IF;
    
    -- Get current role of the user being updated
    SELECT role_in_org INTO current_user_role
    FROM public.users
    WHERE id = p_user_id AND organization_id = p_organization_id;
    
    IF current_user_role IS NULL THEN
        RAISE EXCEPTION 'User is not a member of this organization';
    END IF;
    
    -- Only owners can change other users to owner
    IF p_new_role = 'OWNER' AND updater_role != 'OWNER' THEN
        RAISE EXCEPTION 'Only organization owners can promote users to owner';
    END IF;
    
    -- Only owners can demote other owners
    IF current_user_role = 'OWNER' AND updater_role != 'OWNER' THEN
        RAISE EXCEPTION 'Only organization owners can change owner roles';
    END IF;
    
    -- Update the user's role
    UPDATE public.users
    SET 
        role_in_org = p_new_role,
        is_org_admin = (p_new_role = 'OWNER' OR p_new_role = 'ADMIN')
    WHERE id = p_user_id AND organization_id = p_organization_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Failed to update user role';
    END IF;
    
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_follower_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Increment follower count
        IF NEW.target_type = 'USER' THEN
            UPDATE users SET follower_count = follower_count + 1 WHERE id = NEW.target_id;
        ELSIF NEW.target_type = 'EVENT' THEN
            UPDATE events SET follower_count = follower_count + 1 WHERE id = NEW.target_id;
        ELSIF NEW.target_type = 'CATEGORY' THEN
            UPDATE categories SET follower_count = follower_count + 1 WHERE id = NEW.target_id;
        END IF;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        -- Decrement follower count
        IF OLD.target_type = 'USER' THEN
            UPDATE users SET follower_count = GREATEST(follower_count - 1, 0) WHERE id = OLD.target_id;
        ELSIF OLD.target_type = 'EVENT' THEN
            UPDATE events SET follower_count = GREATEST(follower_count - 1, 0) WHERE id = OLD.target_id;
        ELSIF OLD.target_type = 'CATEGORY' THEN
            UPDATE categories SET follower_count = GREATEST(follower_count - 1, 0) WHERE id = OLD.target_id;
        END IF;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$

