CREATE OR REPLACE FUNCTION public.accept_organization_invitation(p_invitation_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    invitation_record RECORD;
    user_id UUID;
    user_email VARCHAR;
BEGIN
    -- Get current user
    user_id := auth.uid();
    IF user_id IS NULL THEN
        RAISE EXCEPTION 'User must be authenticated';
    END IF;
    
    -- Get user email
    SELECT email INTO user_email FROM auth.users WHERE id = user_id;
    
    -- Get invitation
    SELECT * INTO invitation_record
    FROM public.organization_invitations
    WHERE invitation_token = p_invitation_token
    AND status = 'PENDING'
    AND expires_at > NOW();
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid or expired invitation';
    END IF;
    
    -- Check if invitation is for this user
    IF invitation_record.email != user_email THEN
        RAISE EXCEPTION 'This invitation is not for your email address';
    END IF;
    
    -- Check if user is already in an organization
    IF EXISTS (
        SELECT 1 FROM public.users 
        WHERE id = user_id 
        AND organization_id IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'You are already a member of an organization. Please leave your current organization first.';
    END IF;
    
    -- Add user to organization
    UPDATE public.users
    SET 
        organization_id = invitation_record.organization_id,
        role_in_org = invitation_record.role,
        is_org_admin = (invitation_record.role IN ('OWNER', 'ADMIN')),
        joined_at = NOW()
    WHERE id = user_id;
    
    -- Update organization user count
    UPDATE public.organizations
    SET current_users_count = current_users_count + 1
    WHERE id = invitation_record.organization_id;
    
    -- Mark invitation as accepted
    UPDATE public.organization_invitations
    SET 
        status = 'ACCEPTED',
        accepted_at = NOW(),
        accepted_by = user_id,
        updated_at = NOW()
    WHERE id = invitation_record.id;
    
    -- Create welcome notification
    PERFORM public.create_notification_from_template(
        user_id,
        'ORGANIZATION_WELCOME',
        jsonb_build_object(
            'organization_name', (SELECT name FROM public.organizations WHERE id = invitation_record.organization_id)
        )
    );
    
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_organization_invitation(p_invitation_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    user_id UUID;
    user_email VARCHAR;
BEGIN
    -- Get current user
    user_id := auth.uid();
