    -- Get user email
    SELECT email INTO user_email FROM auth.users WHERE id = user_id;
    
    -- Update invitation status
    UPDATE public.organization_invitations
    SET 
        status = 'REJECTED',
        updated_at = NOW()
    WHERE invitation_token = p_invitation_token
    AND email = user_email
    AND status = 'PENDING'
    AND expires_at > NOW();
    
