CREATE OR REPLACE FUNCTION public.add_review(p_event_id uuid, p_user_id uuid, p_rating integer, p_title character varying DEFAULT NULL::character varying, p_comment text DEFAULT NULL::text, p_is_verified boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    review_id UUID;
BEGIN
    -- Check if user has already reviewed this event
    IF EXISTS (SELECT 1 FROM reviews WHERE event_id = p_event_id AND user_id = p_user_id) THEN
        RAISE EXCEPTION 'User has already reviewed this event';
    END IF;
    
    -- Check if rating is valid
    IF p_rating < 1 OR p_rating > 5 THEN
        RAISE EXCEPTION 'Rating must be between 1 and 5';
    END IF;
    
    -- Insert review
    INSERT INTO reviews (event_id, user_id, rating, title, comment, is_verified)
    VALUES (p_event_id, p_user_id, p_rating, p_title, p_comment, p_is_verified)
    RETURNING id INTO review_id;
    
    RETURN review_id;
END;
$function$

