CREATE OR REPLACE FUNCTION public.leave_organization(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    user_role VARCHAR;
    user_org_id UUID;
    org_owner_id UUID;
BEGIN
    SELECT organization_id, role_in_org 
    INTO user_org_id, user_role 
    FROM public.users 
    WHERE id = p_user_id;
    
    IF user_org_id IS NULL THEN
        RAISE EXCEPTION 'User is not a member of any organization';
    END IF;
    
    SELECT created_by INTO org_owner_id 
    FROM public.organizations 
    WHERE id = user_org_id;
    
    IF user_role = 'OWNER' OR org_owner_id = p_user_id THEN
        RAISE EXCEPTION 'Organization owners cannot leave the organization. Please transfer ownership first or delete the organization.';
    END IF;
    
    UPDATE public.users 
    SET organization_id = NULL, role_in_org = NULL, is_org_admin = FALSE, joined_at = NULL
    WHERE id = p_user_id;
    
    UPDATE public.organizations 
    SET current_users_count = current_users_count - 1
    WHERE id = user_org_id;
    
    RETURN TRUE;
EXCEPTION
    WHEN OTHERS THEN RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_organization_admin_request(p_request_id uuid, p_reviewer_id uuid, p_review_notes text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    request_record RECORD;
    org_owner_id UUID;
BEGIN
    -- Get request details
    SELECT * INTO request_record 
    FROM admin_requests 
    WHERE id = p_request_id AND status = 'PENDING';
    
    IF request_record IS NULL THEN
        RAISE EXCEPTION 'Request not found or not pending';
    END IF;
    
    -- Check if reviewer is organization owner
    SELECT created_by INTO org_owner_id 
    FROM organizations 
    WHERE id = request_record.organization_id;
    
    IF org_owner_id != p_reviewer_id THEN
        RAISE EXCEPTION 'Only organization owners can approve admin requests';
    END IF;
    
    -- Update the request status
    UPDATE admin_requests 
    SET 
        status = 'APPROVED',
        reviewed_by = p_reviewer_id,
        reviewed_at = NOW(),
        review_notes = p_review_notes,
        updated_at = NOW()
    WHERE id = p_request_id;
    
    -- Add user to organization as admin
    PERFORM add_user_to_organization(
        request_record.user_id,
        request_record.organization_id,
        p_reviewer_id,
        request_record.requested_role
    );
    
    -- Send approval notification
    PERFORM send_admin_request_notification(
        request_record.user_id,
        'ADMIN_REQUEST_APPROVED',
        jsonb_build_object(
            'request_id', p_request_id,
            'organization_id', request_record.organization_id,
            'reviewer_id', p_reviewer_id
        )
    );
    
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_event_space(p_space_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    space_org_id UUID;
    user_role VARCHAR;
    event_count INTEGER;
BEGIN
    -- Get the event space details
    SELECT organization_id INTO space_org_id
    FROM event_spaces
    WHERE id = p_space_id;
    
    IF space_org_id IS NULL THEN
        RAISE EXCEPTION 'Event space not found';
    END IF;
    
    -- Check if user has permission (org owner or admin)
    SELECT role_in_org INTO user_role
    FROM users
    WHERE id = p_user_id AND organization_id = space_org_id;
    
    IF user_role IS NULL OR (user_role != 'OWNER' AND user_role != 'ADMIN') THEN
        RAISE EXCEPTION 'Only organization owners and admins can delete event spaces';
    END IF;
    
    -- Check if there are events in this space
    SELECT COUNT(*) INTO event_count
    FROM events
    WHERE event_space_id = p_space_id;
    
    IF event_count > 0 THEN
        RAISE EXCEPTION 'Cannot delete event space that contains events. Please move or delete all events first.';
    END IF;
    
    -- Check if this is the last event space in the organization
    IF (SELECT COUNT(*) FROM event_spaces WHERE organization_id = space_org_id) <= 1 THEN
        RAISE EXCEPTION 'Cannot delete the last event space in an organization. Each organization must have at least one event space.';
    END IF;
    
    -- Delete the event space
    DELETE FROM event_spaces
    WHERE id = p_space_id;
    
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.trigger_follow_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
    target_name TEXT;
    target_type TEXT;
    follower_username TEXT;
BEGIN
    -- Get target details
    IF NEW.target_type = 'USER' THEN
        -- Fix: Get username from public.users, not auth.users
        SELECT COALESCE(username, email) INTO target_name
        FROM public.users
        WHERE id = NEW.target_id;
        target_type := 'user';
    ELSIF NEW.target_type = 'EVENT' THEN
        SELECT title INTO target_name
        FROM events
        WHERE id = NEW.target_id;
        target_type := 'event';
    ELSIF NEW.target_type = 'CATEGORY' THEN
        SELECT name INTO target_name
        FROM categories
        WHERE id = NEW.target_id;
        target_type := 'category';
    END IF;
    
    -- Fix: Get follower username from public.users, not auth.users
    SELECT COALESCE(username, email) INTO follower_username
    FROM public.users
    WHERE id = NEW.follower_id;
    
    -- Create follow notification (only if target is USER to avoid self-notification)
    IF NEW.target_type = 'USER' THEN
        PERFORM create_notification_from_template(
            NEW.target_id,
            'FOLLOW_UPDATE',
            jsonb_build_object(
                'username', follower_username,
                'action', 'started following',
                'target_type', target_type,
                'target_name', target_name
            )
        );
    END IF;
    
    RETURN NEW;
END;
$function$
